SELECT ?zone ?ts WHERE {
  ?zone a brick:Space ;
        rdfs:label ?label ;
        ref:hasTimeseriesId ?ts .
  FILTER(?label IN ("Perimeter_top_ZN_4","Perimeter_top_ZN_3"))
}

SELECT ?node ?class ?label ?ts WHERE {
  ?node a ?class .
  FILTER(str(?node) LCASE("perimeter_top_"))
  OPTIONAL { ?node rdfs:label ?label }
  OPTIONAL { ?node ref:hasTimeseriesId ?ts }
}

SELECT ?node ?label ?ts WHERE {
  ?node ref:hasTimeseriesId ?ts .
  OPTIONAL { ?node rdfs:label ?label }
  FILTER(STRSTARTS(STR(?node), "perimeter_top"))
}

SELECT ?node ?class ?label WHERE {
  ?node a brick:Occupancy .
  OPTIONAL { ?node rdfs:label ?label }
}

